css:
.watchlist-public-shell * { box-sizing:border-box; }
.watchlist-public-shell a:focus-visible,.watchlist-public-shell button:focus-visible { outline:3px solid #2e6fbb; outline-offset:3px; }
.watchlist-public-shell .tl2-header { align-items:center; background:#fff; border-bottom:1px solid #dbe4ef; box-shadow:0 9px 25px rgba(14,47,93,.08); display:flex; justify-content:space-between; min-height:76px; padding:0 4.5%; position:relative; z-index:1; }
.watchlist-public-shell .tl2-logo { display:block; text-decoration:none; }
.watchlist-public-shell .tl2-logo img { display:block; height:32px; width:auto; }
.watchlist-public-shell .tl2-nav { align-items:center; display:flex; gap:24px; }
.watchlist-public-shell .tl2-nav a { color:#385376; font-size:14px; font-weight:600; text-decoration:none; }
.watchlist-public-shell .tl2-features-menu { position:relative; }
.watchlist-public-shell .tl2-features-toggle { align-items:center; background:transparent; border:0; color:#385376; cursor:pointer; display:flex; font:inherit; font-size:14px; font-weight:600; gap:6px; padding:8px 0; white-space:nowrap; }
.watchlist-public-shell .tl2-features-chevron { border:solid currentColor; border-width:0 1.5px 1.5px 0; display:inline-block; height:6px; transform:translateY(-2px) rotate(45deg); transition:transform .2s ease; width:6px; }
.watchlist-public-shell .tl2-features-menu.is-open .tl2-features-chevron { transform:translateY(1px) rotate(225deg); }
.watchlist-public-shell .tl2-features-links { background:#fff; border:1px solid #dbe4ef; border-radius:10px; box-shadow:0 14px 28px rgba(14,47,93,.14); display:none; left:-18px; min-width:206px; padding:8px; position:absolute; top:calc(100% + 11px); z-index:3; }
.watchlist-public-shell .tl2-features-menu.is-open .tl2-features-links { display:grid; gap:2px; }
.watchlist-public-shell .tl2-features-links a { border-radius:7px; padding:10px; }
.watchlist-public-shell .tl2-features-links a:hover { background:#edf4fb; color:#062663; }
.watchlist-public-shell .tl2-nav .tl2-account-link { color:#fff; font-size:14px; margin-left:16px; padding:12px 17px; position:relative; transition:box-shadow .2s ease,transform .2s ease; }
.watchlist-public-shell .tl2-nav .tl2-account-link::before { background:#dbe4ef; content:""; height:24px; left:-16px; position:absolute; top:50%; transform:translateY(-50%); width:1px; }
.watchlist-public-shell .tl2-nav .tl2-account-link:hover { box-shadow:0 7px 15px rgba(6,38,99,.18); transform:translateY(-1px); }
.watchlist-public-shell .tl2-menu-toggle { align-items:center; background:#fff; border:1px solid #c9d6e5; border-radius:8px; cursor:pointer; display:none; height:40px; justify-content:center; padding:0; width:40px; }
.watchlist-public-shell .tl2-menu-toggle-lines { display:grid; gap:4px; width:18px; }
.watchlist-public-shell .tl2-menu-toggle-lines span { background:#173761; border-radius:2px; display:block; height:2px; transition:opacity .2s ease,transform .2s ease; }
.watchlist-public-shell .tl2-header.is-menu-open .tl2-menu-toggle-lines span:nth-child(1) { transform:translateY(6px) rotate(45deg); }
.watchlist-public-shell .tl2-header.is-menu-open .tl2-menu-toggle-lines span:nth-child(2) { opacity:0; }
.watchlist-public-shell .tl2-header.is-menu-open .tl2-menu-toggle-lines span:nth-child(3) { transform:translateY(-6px) rotate(-45deg); }
.watchlist-public-shell .tl2-account-link { background:#062663; border:1px solid #062663; border-radius:7px; color:#fff; display:inline-block; font-size:16px; font-weight:700; padding:14px 22px; text-decoration:none; }
.watchlist-public-shell .tl2-intro .tl2-account-link { margin-top:28px; }
.watchlist-public-shell .tl2-signup .tl2-account-link { background:#fff; border-color:#fff; color:#062663; }
.watchlist-public-shell .tl2-legal { align-items:center; background:#062663; color:#d8e4f8; display:flex; flex-wrap:wrap; gap:12px 20px; justify-content:space-between; padding:24px 4.5%; }
.watchlist-public-shell .tl2-legal p { margin:0; }
.watchlist-public-shell .tl2-legal-links { display:flex; flex-wrap:wrap; gap:20px; }
.watchlist-public-shell .tl2-legal a { color:#fff; font-size:14px; font-weight:700; text-decoration:underline; text-underline-offset:3px; }
@media (prefers-reduced-motion:reduce) { .watchlist-public-shell .tl2-nav .tl2-account-link,.watchlist-public-shell .tl2-features-chevron,.watchlist-public-shell .tl2-menu-toggle-lines span { transition:none; } .watchlist-public-shell .tl2-nav .tl2-account-link:hover { transform:none; } }
@media (max-width:760px) {
  .watchlist-public-shell .tl2-header { min-height:68px; padding:0 18px; z-index:30; }
  .watchlist-public-shell .tl2-logo img { height:27px; }
  .watchlist-public-shell .tl2-menu-toggle { display:flex; }
  .watchlist-public-shell .tl2-nav { align-items:stretch; background:#fff; border:1px solid #d6e1ed; border-radius:12px; box-shadow:0 18px 38px rgba(14,47,93,.18); display:none; flex-direction:column; gap:2px; left:12px; padding:10px; position:absolute; right:12px; top:calc(100% + 8px); }
  .watchlist-public-shell .tl2-header.is-menu-open .tl2-nav { display:flex; }
  .watchlist-public-shell .tl2-nav > a:not(.tl2-account-link) { border-radius:8px; padding:10px 12px; }
  .watchlist-public-shell .tl2-features-menu { display:block; }
  .watchlist-public-shell .tl2-features-toggle { justify-content:space-between; padding:10px 12px; width:100%; }
  .watchlist-public-shell .tl2-features-links { box-shadow:none; left:auto; margin:2px 0 6px; min-width:0; position:static; top:auto; }
  .watchlist-public-shell .tl2-nav .tl2-account-link { align-self:flex-start; font-size:13px; margin:6px 0 0 12px; padding:8px 12px; }
  .watchlist-public-shell .tl2-nav .tl2-account-link::before { display:none; }
  .watchlist-public-shell .tl2-legal { align-items:flex-start; flex-direction:column; }
}

.watchlist-public-shell .seo-footer-links { display:flex; flex-wrap:wrap; justify-content:center; gap:12px 22px; margin:16px 0; }
.watchlist-public-shell .seo-footer-links a { color:#174ea6; text-decoration:underline; text-underline-offset:3px; }
.watchlist-public-shell .seo-footer-links a { font-size:14px; font-weight:600; }
